(function () {
  'use strict';

  const IMAGE_FALLBACKS = {"images/python.png": "data:image/png;base64,", "images/r.png": "data:image/png;base64,", "images/sql.png": "data:image/png;base64,", "images/java.png": "data:image/png;base64,", "images/matlab.png": "data:image/png;base64,", "images/tensorflow.png": "data:image/png;base64,", "images/pytorch.png": "data:image/png;base64,", "images/scikitlearn.png": "data:image/png;base64,", "images/cnn.png": "data:image/png;base64,", "images/fe.png": "data:image/png;base64,", "images/tableau.png": "data:image/png;base64,", "images/powerbi.png": "data:image/png;base64,", "images/pandas.png": "data:image/png;base64,", "images/numpy.png": "data:image/png;base64,", "images/matplotlib.png": "data:image/png;base64,", "images/streamlit.png": "data:image/png;base64,", "images/jupyter.png": "data:image/png;base64,", "images/mongodb.png": "data:image/png;base64,", "images/neo4j.png": "data:image/png;base64,", "images/mysql.png": "data:image/png;base64,", "images/git.png": "data:image/png;base64,", "images/aws.png": "data:image/png;base64,", "images/oci.png": "data:image/png;base64,", "images/avatar.png": "data:image/jpeg;base64,", "images/profile.jpg": "data:image/jpeg;base64,"};

  function attachImageFallbacks() {
    document.querySelectorAll('img[data-src-key]').forEach((img) => {
      const key = img.getAttribute('data-src-key');
      img.addEventListener('error', function () {
        if (IMAGE_FALLBACKS[key] && img.src !== IMAGE_FALLBACKS[key]) {
          img.src = IMAGE_FALLBACKS[key];
        }
      });
      if (img.complete && img.naturalWidth === 0 && IMAGE_FALLBACKS[key]) {
        img.src = IMAGE_FALLBACKS[key];
      }
    });
  }
  attachImageFallbacks();
  window.addEventListener('load', attachImageFallbacks);

  // 1. Light (Warm Beige) / Dark Mode Theme Switcher
  const htmlEl = document.documentElement;
  const themeBtns = document.querySelectorAll('.theme-btn');

  function setTheme(mode) {
    const normalized = mode === 'beige' ? 'light' : mode;
    htmlEl.setAttribute('data-theme', normalized);
    themeBtns.forEach((btn) => {
      btn.classList.toggle('active', btn.getAttribute('data-theme-val') === normalized);
    });
    try {
      localStorage.setItem('ak_portfolio_theme', normalized);
    } catch (e) {}
  }

  themeBtns.forEach((btn) => {
    btn.addEventListener('click', () => {
      setTheme(btn.getAttribute('data-theme-val'));
    });
  });

  try {
    const saved = localStorage.getItem('ak_portfolio_theme');
    if (saved === 'dark' || saved === 'light' || saved === 'beige') {
      setTheme(saved);
    }
  } catch (e) {}

  // 2. Top Scroll Progress Bar & Active Navigation Scroll-Spy
  const scrollBar = document.getElementById('scroll-progress-bar');
  const sections = document.querySelectorAll('section[id]');
  const navLinks = document.querySelectorAll('.nav-menu a');

  window.addEventListener('scroll', () => {
    const scrollTop = document.documentElement.scrollTop || document.body.scrollTop;
    const docHeight = document.documentElement.scrollHeight - document.documentElement.clientHeight;
    if (scrollBar && docHeight > 0) {
      scrollBar.style.width = ((scrollTop / docHeight) * 100).toFixed(1) + '%';
    }

    let currentSec = '';
    sections.forEach((sec) => {
      const top = sec.offsetTop - 130;
      if (scrollTop >= top) {
        currentSec = sec.getAttribute('id');
      }
    });
    if (currentSec) {
      navLinks.forEach((link) => {
        link.classList.toggle('active', link.getAttribute('href') === '#' + currentSec);
      });
    }
  });

  // 3. Staggered Scroll-Reveal Animation
  const revealItems = document.querySelectorAll('.reveal');
  if ('IntersectionObserver' in window) {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('visible');
            observer.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.1, rootMargin: '0px 0px -30px 0px' }
    );
    revealItems.forEach((el) => observer.observe(el));
  } else {
    revealItems.forEach((el) => el.classList.add('visible'));
  }

  // 4. Animated Hero Number Counters
  function animateCounters() {
    document.querySelectorAll('[data-count-to]').forEach((el) => {
      const target = parseFloat(el.getAttribute('data-count-to'));
      const decimals = parseInt(el.getAttribute('data-decimals') || '0', 10);
      const prefix = el.getAttribute('data-prefix') || '';
      const suffix = el.getAttribute('data-suffix') || '';
      const duration = 1400;
      const startTime = performance.now();

      function tick(now) {
        const progress = Math.min((now - startTime) / duration, 1);
        const eased = 1 - Math.pow(1 - progress, 3);
        const current = (target * eased).toFixed(decimals);
        el.textContent = prefix + current + suffix;
        if (progress < 1) {
          requestAnimationFrame(tick);
        }
      }
      requestAnimationFrame(tick);
    });
  }
  animateCounters();

  // 5. Animated Focus Ticker in Hero
  const focusPhrases = [
    'Exploring LLMs & RAG Pipelines • Open to 2026 DS/ML Roles',
    'Building Intelligent Knowledge Graphs with Neo4j & NetworkX',
    'Training Deep Learning Models in PyTorch & TensorFlow',
    'Designing Interactive R Shiny & Streamlit Analytics Apps'
  ];
  const focusTextEl = document.getElementById('focus-dynamic-text');
  let focusIdx = 0;
  if (focusTextEl) {
    setInterval(() => {
      focusTextEl.classList.add('fade-out');
      setTimeout(() => {
        focusIdx = (focusIdx + 1) % focusPhrases.length;
        focusTextEl.textContent = focusPhrases[focusIdx];
        focusTextEl.classList.remove('fade-out');
      }, 300);
    }, 3400);
  }

  // 6. Hero Portrait Crossfade Toggle & 3D Hover Tilt
  const heroImg = document.getElementById('hero-portrait-img');
  const toggleArtBtn = document.getElementById('toggle-art-btn');
  const portraitCard = document.getElementById('portrait-tilt-card');
  let showingPhoto = true;

  if (toggleArtBtn && heroImg) {
    toggleArtBtn.addEventListener('click', () => {
      heroImg.classList.add('switching');
      setTimeout(() => {
        showingPhoto = !showingPhoto;
        if (showingPhoto) {
          heroImg.setAttribute('data-src-key', 'images/profile.jpg');
          heroImg.src = IMAGE_FALLBACKS['images/profile.jpg'] || 'images/profile.jpg';
          toggleArtBtn.textContent = 'Switch to Vector';
        } else {
          heroImg.setAttribute('data-src-key', 'images/avatar.png');
          heroImg.src = IMAGE_FALLBACKS['images/avatar.png'] || 'images/avatar.png';
          toggleArtBtn.textContent = 'Switch to Photo';
        }
        heroImg.classList.remove('switching');
      }, 220);
    });
  }

  if (portraitCard) {
    portraitCard.addEventListener('mousemove', (e) => {
      const rect = portraitCard.getBoundingClientRect();
      const x = (e.clientX - rect.left) / rect.width - 0.5;
      const y = (e.clientY - rect.top) / rect.height - 0.5;
      portraitCard.style.transform = `perspective(800px) rotateY(${(x * 7).toFixed(2)}deg) rotateX(${(-y * 7).toFixed(2)}deg)`;
    });
    portraitCard.addEventListener('mouseleave', () => {
      portraitCard.style.transform = '';
    });
  }

  // 7. Mobile Navigation Menu
  const menuBtn = document.getElementById('menu-toggle-btn');
  const navMenu = document.getElementById('nav-menu');
  if (menuBtn && navMenu) {
    menuBtn.addEventListener('click', () => navMenu.classList.toggle('open'));
    navMenu.querySelectorAll('a').forEach((link) => {
      link.addEventListener('click', () => navMenu.classList.remove('open'));
    });
  }

  // 8. Skill Image Grid Category Filtering & Project Cross-Highlighting
  const skillFilterBtns = document.querySelectorAll('[data-skill-filter]');
  const skillCards = document.querySelectorAll('.skill-img-card');
  const projectCards = document.querySelectorAll('.editorial-project-card');
  const filterStatus = document.getElementById('skill-filter-status');

  skillFilterBtns.forEach((btn) => {
    btn.addEventListener('click', () => {
      skillFilterBtns.forEach((b) => b.classList.remove('active'));
      btn.classList.add('active');
      const cat = btn.getAttribute('data-skill-filter');

      let delay = 0;
      skillCards.forEach((card) => {
        const match = cat === 'all' || card.getAttribute('data-cat') === cat;
        card.classList.toggle('hidden', !match);
        if (match) {
          card.classList.remove('pop-animate');
          void card.offsetWidth;
          card.style.animationDelay = delay + 'ms';
          card.classList.add('pop-animate');
          delay += 25;
        }
      });
    });
  });

  skillCards.forEach((card) => {
    card.addEventListener('click', () => {
      const isAlreadySelected = card.classList.contains('selected');
      skillCards.forEach((c) => c.classList.remove('selected'));
      projectCards.forEach((p) => p.classList.remove('highlight-match'));

      if (isAlreadySelected) {
        if (filterStatus) filterStatus.textContent = 'Click any skill card above to highlight matching projects.';
        return;
      }

      card.classList.add('selected');
      const skillName = card.getAttribute('data-skill-name') || '';
      const kw = skillName.toLowerCase();
      let matchCount = 0;

      projectCards.forEach((proj) => {
        const stack = (proj.getAttribute('data-stack') || '').toLowerCase();
        if (stack.includes(kw) || kw.includes('python') || kw.includes('git')) {
          proj.classList.add('highlight-match');
          matchCount++;
        }
      });

      if (filterStatus) {
        filterStatus.textContent = `Highlighted ${matchCount} project(s) utilizing ${skillName}.`;
      }
    });
  });

  // 9. Project Domain Filter & Accordion Drawer
  const projFilterBtns = document.querySelectorAll('[data-proj-filter]');
  projFilterBtns.forEach((btn) => {
    btn.addEventListener('click', () => {
      projFilterBtns.forEach((b) => b.classList.remove('active'));
      btn.classList.add('active');
      const dom = btn.getAttribute('data-proj-filter');

      let delay = 0;
      projectCards.forEach((card) => {
        const show = dom === 'all' || card.getAttribute('data-domain') === dom;
        card.style.display = show ? 'flex' : 'none';
        if (show) {
          card.classList.remove('pop-animate');
          void card.offsetWidth;
          card.style.animationDelay = delay + 'ms';
          card.classList.add('pop-animate');
          delay += 45;
        }
      });
    });
  });

  window.toggleCaseStudy = function (btnEl, drawerId) {
    const drawer = document.getElementById(drawerId);
    if (!drawer) return;
    const isOpen = drawer.classList.toggle('open');
    btnEl.textContent = isOpen ? 'Hide Details −' : 'Details +';
  };

  // 10. IEEE Research Paper Interactive Dimension Tabs
  const expData = {
    lr: {
      title: 'Dynamic Learning Rate Schedules',
      body: 'Investigated how dynamic learning rate adjustments interact with optimizers and activations during CNN training, accelerating early convergence while stabilizing final validation accuracy.'
    },
    opt: {
      title: 'Optimizer Dynamics (PyTorch & TensorFlow)',
      body: 'Empirically evaluated gradient updates across optimizers on benchmark computer vision datasets using PyTorch, TensorFlow, OpenCV, NumPy, and Scikit-learn.'
    },
    act: {
      title: 'Activation Function Synergy',
      body: 'Uncovered non-linear interactions when activation functions and optimizers are tuned in concert, achieving significant gains in generalization (IEEE 5th ICAISP 2025, Impact Factor: 2.8).'
    }
  };

  const expTabs = document.querySelectorAll('.exp-tab');
  const expPane = document.getElementById('exp-detail-pane');
  expTabs.forEach((tab) => {
    tab.addEventListener('click', () => {
      expTabs.forEach((t) => t.classList.remove('active'));
      tab.classList.add('active');
      const key = tab.getAttribute('data-exp');
      if (expData[key] && expPane) {
        expPane.style.animation = 'none';
        void expPane.offsetWidth;
        expPane.style.animation = 'slideDownFade 0.28s ease';
        expPane.innerHTML = `<strong style="color: var(--ink-primary); display:block; margin-bottom:6px;">${expData[key].title}</strong>${expData[key].body}`;
      }
    });
  });

  // 11. Copy to Clipboard & Direct Email Composer
  window.copyInfo = function (value, label) {
    if (navigator.clipboard) {
      navigator.clipboard.writeText(value);
    }
    const toast = document.getElementById('toast-banner');
    if (toast) {
      toast.textContent = label;
      toast.classList.add('show');
      setTimeout(() => toast.classList.remove('show'), 2500);
    }
  };

  const contactForm = document.getElementById('editorial-contact-form');
  if (contactForm) {
    contactForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const name = document.getElementById('f-name').value.trim();
      const subj = document.getElementById('f-subj').value.trim();
      const msg = document.getElementById('f-msg').value.trim();
      window.location.href = `mailto:abhishek.k.jalandhar@gmail.com?subject=${encodeURIComponent(subj + ' — from ' + name)}&body=${encodeURIComponent(msg)}`;
    });
  }

  // =========================================================================
  // 12. HARD-CODED 60FPS CHARACTER & SCENE ANIMATION ENGINE
  //     Every section and card features a bespoke procedural HTML5 Canvas
  //     scene illustrating the exact activity (coding + live charts at Toeho
  //     AI, reviewing policies at LIC, showing excellence at TCS NQT, CNN
  //     neural pulses, project scenes, graduation, certificates & contact).
  // =========================================================================
  function getPalette() {
    const isDark = htmlEl.getAttribute('data-theme') === 'dark';
    return isDark
      ? {
          bg: '#191613',
          surface: '#26211D',
          border: '#423A32',
          ink: '#F4EFE6',
          muted: '#9E9488',
          terracotta: '#E07A5F',
          sage: '#81B29A',
          gold: '#F2CC8F',
          skin: '#E0AC8B',
          hair: '#1A1615',
          shirt: '#3D5A4B'
        }
      : {
          bg: '#EFE7DA',
          surface: '#FBF8F3',
          border: '#C8B9A6',
          ink: '#1C1917',
          muted: '#78716C',
          terracotta: '#B8502B',
          sage: '#2D5A43',
          gold: '#C87D20',
          skin: '#D99B72',
          hair: '#231F1D',
          shirt: '#2D5A43'
        };
  }

  function rRect(ctx, x, y, w, h, r) {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
  }

  // Helper: Draw a stylized person head & torso
  function drawPerson(ctx, x, y, pal, headBob, shirtColor) {
    // Shoulders / Torso
    ctx.fillStyle = shirtColor || pal.shirt;
    rRect(ctx, x - 20, y + 12, 40, 34, 12);
    ctx.fill();
    // Neck
    ctx.fillStyle = pal.skin;
    ctx.fillRect(x - 5, y + 4, 10, 10);
    // Head
    ctx.beginPath();
    ctx.arc(x, y - 4 + headBob, 13, 0, Math.PI * 2);
    ctx.fillStyle = pal.skin;
    ctx.fill();
    // Hair
    ctx.beginPath();
    ctx.arc(x, y - 7 + headBob, 13.5, Math.PI, Math.PI * 2);
    ctx.fillStyle = pal.hair;
    ctx.fill();
    // Glasses
    ctx.strokeStyle = pal.ink;
    ctx.lineWidth = 1.4;
    ctx.strokeRect(x - 8, y - 7 + headBob, 6, 4.5);
    ctx.strokeRect(x + 2, y - 7 + headBob, 6, 4.5);
    ctx.beginPath();
    ctx.moveTo(x - 2, y - 5 + headBob);
    ctx.lineTo(x + 2, y - 5 + headBob);
    ctx.stroke();
  }

  const SCENE_RENDERERS = {
    // 1. TOEHO AI: Person coding on laptop + making live stock/analytics charts
    toeho: function (ctx, w, h, t, pal) {
      const deskY = h - 22;
      // Desk line
      ctx.strokeStyle = pal.border;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(16, deskY);
      ctx.lineTo(w - 16, deskY);
      ctx.stroke();

      // Person coding on left
      const px = w * 0.23;
      const py = deskY - 44;
      const bob = Math.sin(t * 4) * 1.6;
      drawPerson(ctx, px, py, pal, bob, pal.terracotta);

      // Animated typing hands
      const handL = Math.sin(t * 15) * 3;
      const handR = Math.cos(t * 15) * 3;
      ctx.fillStyle = pal.skin;
      ctx.beginPath();
      ctx.arc(px + 20, deskY - 6 + handL, 4, 0, Math.PI * 2);
      ctx.arc(px + 29, deskY - 6 + handR, 4, 0, Math.PI * 2);
      ctx.fill();

      // Laptop on desk
      ctx.fillStyle = pal.ink;
      rRect(ctx, px + 26, deskY - 28, 36, 24, 4);
      ctx.fill();
      ctx.fillRect(px + 18, deskY - 4, 46, 4);

      // Scrolling code lines inside laptop screen
      ctx.strokeStyle = pal.sage;
      ctx.lineWidth = 2;
      for (let i = 0; i < 4; i++) {
        const lineW = 10 + ((i * 7 + Math.floor(t * 6)) % 18);
        ctx.beginPath();
        ctx.moveTo(px + 31, deskY - 22 + i * 5);
        ctx.lineTo(px + 31 + lineW, deskY - 22 + i * 5);
        ctx.stroke();
      }

      // Live Analytics Dashboard Monitor on right
      const bx = w * 0.52;
      const by = 18;
      const bw = w * 0.42;
      const bh = deskY - 26;
      ctx.fillStyle = pal.surface;
      ctx.strokeStyle = pal.border;
      ctx.lineWidth = 1.5;
      rRect(ctx, bx, by, bw, bh, 8);
      ctx.fill();
      ctx.stroke();

      // Animated Bar Chart inside dashboard
      const barCount = 5;
      const barW = Math.max(6, (bw - 36) / (barCount * 1.8));
      for (let i = 0; i < barCount; i++) {
        const animH = (0.3 + 0.55 * Math.abs(Math.sin(t * 2.2 + i * 0.9))) * (bh - 28);
        const x = bx + 14 + i * (barW + 6);
        const y = by + bh - 10 - animH;
        ctx.fillStyle = i % 2 === 0 ? pal.sage : pal.terracotta;
        rRect(ctx, x, y, barW, animH, 2);
        ctx.fill();
      }

      // Animated Live Stock Line Trend Overlay
      ctx.beginPath();
      ctx.strokeStyle = pal.gold;
      ctx.lineWidth = 2.2;
      for (let i = 0; i <= 20; i++) {
        const x = bx + 10 + (i / 20) * (bw - 20);
        const y = by + bh * 0.45 - Math.sin(t * 3 + i * 0.45) * (bh * 0.22);
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.stroke();
    },

    // 2. LIC OF INDIA: Person reviewing insurance policy with magnifying glass & checkmarks
    lic: function (ctx, w, h, t, pal) {
      const deskY = h - 22;
      ctx.strokeStyle = pal.border;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(16, deskY);
      ctx.lineTo(w - 16, deskY);
      ctx.stroke();

      // Agent on left
      const px = w * 0.24;
      const py = deskY - 44;
      const bob = Math.sin(t * 2.5) * 1.5;
      drawPerson(ctx, px, py, pal, bob, pal.sage);

      // Large Policy Document floating in center
      const dx = w * 0.46;
      const dy = 16;
      const dw = 68;
      const dh = deskY - 22;
      ctx.fillStyle = pal.surface;
      ctx.strokeStyle = pal.border;
      ctx.lineWidth = 1.6;
      rRect(ctx, dx, dy, dw, dh, 6);
      ctx.fill();
      ctx.stroke();

      // Policy Header & Lines + Animated Checkmarks
      ctx.fillStyle = pal.terracotta;
      ctx.fillRect(dx + 10, dy + 10, dw - 20, 5);

      const activeRow = Math.floor((t * 1.8) % 4);
      for (let i = 0; i < 4; i++) {
        const ly = dy + 25 + i * 14;
        ctx.strokeStyle = i <= activeRow ? pal.ink : pal.muted;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(dx + 22, ly);
        ctx.lineTo(dx + dw - 10, ly);
        ctx.stroke();

        // Checkmark box
        if (i <= activeRow) {
          ctx.strokeStyle = pal.sage;
          ctx.lineWidth = 2;
          ctx.beginPath();
          ctx.moveTo(dx + 9, ly - 1);
          ctx.lineTo(dx + 12, ly + 2);
          ctx.lineTo(dx + 17, ly - 4);
          ctx.stroke();
        }
      }

      // Animated Magnifying Glass scanning over policy
      const mx = dx + 34 + Math.cos(t * 2.2) * 14;
      const my = dy + 38 + Math.sin(t * 2.2) * 14;
      ctx.beginPath();
      ctx.arc(mx, my, 12, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(224, 122, 95, 0.15)';
      ctx.fill();
      ctx.strokeStyle = pal.terracotta;
      ctx.lineWidth = 2.2;
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(mx + 8, my + 8);
      ctx.lineTo(mx + 16, my + 16);
      ctx.stroke();

      // Protection Shield Emblem on right
      const sx = w * 0.83;
      const sy = h * 0.45 + Math.sin(t * 3) * 3;
      ctx.beginPath();
      ctx.moveTo(sx, sy - 18);
      ctx.lineTo(sx + 16, sy - 10);
      ctx.lineTo(sx + 16, sy + 4);
      ctx.quadraticCurveTo(sx, sy + 20, sx, sy + 22);
      ctx.quadraticCurveTo(sx, sy + 20, sx - 16, sy + 4);
      ctx.lineTo(sx - 16, sy - 10);
      ctx.closePath();
      ctx.fillStyle = pal.sage;
      ctx.fill();
    },

    // 3. ACHIEVEMENT (TCS NQT): Person showing excellence on podium with trophy & stars
    achievement: function (ctx, w, h, t, pal) {
      const base = h - 18;
      // Podium steps
      ctx.fillStyle = pal.border;
      rRect(ctx, w * 0.18, base - 24, 44, 24, 4);
      ctx.fill();
      ctx.fillStyle = pal.sage;
      rRect(ctx, w * 0.36, base - 38, 54, 38, 4);
      ctx.fill();
      ctx.fillStyle = pal.border;
      rRect(ctx, w * 0.58, base - 18, 44, 18, 4);
      ctx.fill();

      // Person on top podium celebrating
      const px = w * 0.36 + 27;
      const py = base - 82;
      const jump = Math.abs(Math.sin(t * 3.5)) * -5;
      drawPerson(ctx, px, py + jump, pal, 0, pal.terracotta);

      // Raised Victory Arms
      ctx.strokeStyle = pal.terracotta;
      ctx.lineWidth = 4.5;
      ctx.lineCap = 'round';
      const wave = Math.sin(t * 6) * 5;
      ctx.beginPath();
      ctx.moveTo(px - 16, py + 18 + jump);
      ctx.lineTo(px - 28, py - 4 + jump + wave);
      ctx.moveTo(px + 16, py + 18 + jump);
      ctx.lineTo(px + 28, py - 8 + jump - wave);
      ctx.stroke();

      // Glowing Trophy in right hand
      const tx = px + 30;
      const ty = py - 18 + jump - wave;
      ctx.fillStyle = pal.gold;
      ctx.beginPath();
      ctx.arc(tx, ty, 9, 0, Math.PI);
      ctx.fill();
      ctx.fillRect(tx - 9, ty - 6, 18, 6);
      ctx.fillRect(tx - 2, ty + 9, 4, 6);
      ctx.fillRect(tx - 6, ty + 14, 12, 3);

      // Orbiting Excellence Stars / Sparkles
      for (let i = 0; i < 6; i++) {
        const ang = t * 1.6 + i * ((Math.PI * 2) / 6);
        const sx = px + Math.cos(ang) * 58;
        const sy = py + 6 + Math.sin(ang) * 26;
        const r = 2.5 + Math.sin(t * 5 + i) * 1.2;
        ctx.fillStyle = i % 2 === 0 ? pal.gold : pal.terracotta;
        ctx.beginPath();
        ctx.arc(sx, sy, Math.max(1, r), 0, Math.PI * 2);
        ctx.fill();
      }
    },

    // 4. IEEE RESEARCH: CNN Layers with animated forward-pass pulses & accuracy curve
    research: function (ctx, w, h, t, pal) {
      const layers = [3, 4, 4, 2];
      const lxStep = (w * 0.52) / (layers.length - 1);
      const startX = 24;
      const coords = [];

      for (let l = 0; l < layers.length; l++) {
        const count = layers[l];
        const col = [];
        for (let n = 0; n < count; n++) {
          const x = startX + l * lxStep;
          const y = (h / (count + 1)) * (n + 1);
          col.push({ x, y });
        }
        coords.push(col);
      }

      // Connections & animated pulse signal
      const activeLayer = (t * 2.2) % (layers.length - 1);
      for (let l = 0; l < coords.length - 1; l++) {
        for (let a of coords[l]) {
          for (let b of coords[l + 1]) {
            ctx.strokeStyle = pal.border;
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(a.x, a.y);
            ctx.lineTo(b.x, b.y);
            ctx.stroke();

            if (Math.floor(activeLayer) === l) {
              const frac = activeLayer - l;
              const px = a.x + (b.x - a.x) * frac;
              const py = a.y + (b.y - a.y) * frac;
              ctx.fillStyle = pal.terracotta;
              ctx.beginPath();
              ctx.arc(px, py, 2.6, 0, Math.PI * 2);
              ctx.fill();
            }
          }
        }
      }

      // Draw CNN Nodes
      for (let l = 0; l < coords.length; l++) {
        for (let node of coords[l]) {
          ctx.beginPath();
          ctx.arc(node.x, node.y, 6, 0, Math.PI * 2);
          ctx.fillStyle = l === coords.length - 1 ? pal.sage : pal.surface;
          ctx.fill();
          ctx.strokeStyle = pal.terracotta;
          ctx.lineWidth = 2;
          ctx.stroke();
        }
      }

      // Live Accuracy Convergence Mini-Chart on Right
      const cx = w * 0.64;
      const cy = 20;
      const cw = w * 0.31;
      const ch = h - 40;
      ctx.fillStyle = pal.surface;
      ctx.strokeStyle = pal.border;
      rRect(ctx, cx, cy, cw, ch, 8);
      ctx.fill();
      ctx.stroke();

      const prog = (t * 0.45) % 1;
      const maxPts = Math.floor(2 + prog * 22);
      ctx.beginPath();
      ctx.strokeStyle = pal.sage;
      ctx.lineWidth = 2.5;
      for (let i = 0; i <= maxPts; i++) {
        const x = cx + 8 + (i / 24) * (cw - 16);
        const y = cy + ch - 10 - (1 - Math.exp(-i * 0.22)) * (ch - 22);
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.stroke();
    },

    // 5. PROJECT 1 — Graph Net (Knowledge Graph Crawler & Node Sequencing)
    'proj-graph': function (ctx, w, h, t, pal) {
      const cx = w / 2;
      const cy = h / 2;
      const nodes = [];
      const count = 7;
      for (let i = 0; i < count; i++) {
        const ang = (i / count) * Math.PI * 2 + t * 0.4;
        const rad = i === 0 ? 0 : 38 + Math.sin(t * 2 + i) * 6;
        nodes.push({
          x: cx + Math.cos(ang) * rad,
          y: cy + Math.sin(ang) * (rad * 0.72)
        });
      }
      ctx.strokeStyle = pal.border;
      ctx.lineWidth = 1.5;
      for (let i = 1; i < nodes.length; i++) {
        ctx.beginPath();
        ctx.moveTo(nodes[0].x, nodes[0].y);
        ctx.lineTo(nodes[i].x, nodes[i].y);
        ctx.stroke();
        const next = nodes[(i % (nodes.length - 1)) + 1];
        ctx.beginPath();
        ctx.moveTo(nodes[i].x, nodes[i].y);
        ctx.lineTo(next.x, next.y);
        ctx.stroke();
      }
      nodes.forEach((n, idx) => {
        ctx.beginPath();
        ctx.arc(n.x, n.y, idx === 0 ? 10 : 6.5, 0, Math.PI * 2);
        ctx.fillStyle = idx === 0 ? pal.terracotta : pal.sage;
        ctx.fill();
      });
    },

    // 6. PROJECT 2 — ARG No-Code ML (Drag-and-Drop Pipeline Blocks)
    'proj-arg': function (ctx, w, h, t, pal) {
      const labels = ['DATA', 'CLEAN', 'MODEL', 'DEPLOY'];
      const bw = 54;
      const bh = 32;
      const gap = (w - labels.length * bw - 40) / (labels.length - 1);
      const y = h / 2 - bh / 2;
      const activeIdx = Math.floor((t * 1.8) % labels.length);

      labels.forEach((lbl, i) => {
        const x = 20 + i * (bw + gap);
        const lift = i === activeIdx ? -5 : 0;
        ctx.fillStyle = i === activeIdx ? pal.terracotta : pal.surface;
        ctx.strokeStyle = pal.border;
        ctx.lineWidth = 1.6;
        rRect(ctx, x, y + lift, bw, bh, 7);
        ctx.fill();
        ctx.stroke();

        ctx.fillStyle = i === activeIdx ? '#FFFFFF' : pal.ink;
        ctx.font = 'bold 9px monospace';
        ctx.textAlign = 'center';
        ctx.fillText(lbl, x + bw / 2, y + lift + 19);

        if (i < labels.length - 1) {
          ctx.strokeStyle = pal.sage;
          ctx.lineWidth = 2;
          ctx.beginPath();
          ctx.moveTo(x + bw + 3, h / 2);
          ctx.lineTo(x + bw + gap - 3, h / 2);
          ctx.stroke();
        }
      });
    },

    // 7. PROJECT 3 — Stock Price Prediction (Candlesticks + KNN Forecast Line)
    'proj-stockpred': function (ctx, w, h, t, pal) {
      const count = 9;
      const step = (w - 40) / count;
      for (let i = 0; i < count; i++) {
        const x = 24 + i * step;
        const v = Math.sin(t * 2 + i * 0.7);
        const ch = 14 + Math.abs(v) * 22;
        const cy = h / 2 - v * 16 - ch / 2;
        ctx.strokeStyle = v >= 0 ? pal.sage : pal.terracotta;
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.moveTo(x + 4, cy - 6);
        ctx.lineTo(x + 4, cy + ch + 6);
        ctx.stroke();
        ctx.fillStyle = v >= 0 ? pal.sage : pal.terracotta;
        rRect(ctx, x, cy, 8, ch, 2);
        ctx.fill();
      }
      // Forecast dashed trajectory
      ctx.beginPath();
      ctx.strokeStyle = pal.gold;
      ctx.lineWidth = 2.2;
      for (let i = 0; i <= 20; i++) {
        const x = 20 + (i / 20) * (w - 40);
        const y = h * 0.55 - Math.sin(t * 2 + i * 0.3) * 22;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.stroke();
    },

    // 8. PROJECT 4 — Stock Analysis & Comparison Tool (Dual Competing Lines)
    'proj-stockcomp': function (ctx, w, h, t, pal) {
      [
        { color: pal.terracotta, phase: 0 },
        { color: pal.sage, phase: 2.1 }
      ].forEach((serie) => {
        ctx.beginPath();
        ctx.strokeStyle = serie.color;
        ctx.lineWidth = 2.6;
        for (let i = 0; i <= 28; i++) {
          const x = 20 + (i / 28) * (w - 40);
          const y = h / 2 + Math.sin(t * 2.5 + i * 0.32 + serie.phase) * 28;
          if (i === 0) ctx.moveTo(x, y);
          else ctx.lineTo(x, y);
        }
        ctx.stroke();
      });
    },

    // 9. PROJECT 5 — Dynamic R Dataset Analysis (Animated Gaussian Bell Curve)
    'proj-rshiny': function (ctx, w, h, t, pal) {
      const spread = 0.85 + Math.sin(t * 2.2) * 0.25;
      ctx.beginPath();
      ctx.strokeStyle = pal.terracotta;
      ctx.lineWidth = 2.6;
      for (let i = 0; i <= 40; i++) {
        const norm = (i / 40 - 0.5) * 4;
        const x = 24 + (i / 40) * (w - 48);
        const gauss = Math.exp(-(norm * norm) / spread);
        const y = h - 20 - gauss * (h - 42);
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.stroke();

      // Baseline
      ctx.strokeStyle = pal.border;
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(20, h - 20);
      ctx.lineTo(w - 20, h - 20);
      ctx.stroke();
    },

    // 10. PROJECT 6 — AI E-Learning Chatbot (Voice Equalizer + Chat Bubble)
    'proj-chatbot': function (ctx, w, h, t, pal) {
      // Bot Head on left
      const bx = w * 0.28;
      const by = h / 2;
      ctx.fillStyle = pal.surface;
      ctx.strokeStyle = pal.terracotta;
      ctx.lineWidth = 2;
      rRect(ctx, bx - 22, by - 20, 44, 38, 10);
      ctx.fill();
      ctx.stroke();

      // Antenna
      ctx.beginPath();
      ctx.moveTo(bx, by - 20);
      ctx.lineTo(bx, by - 30);
      ctx.stroke();
      ctx.beginPath();
      ctx.arc(bx, by - 32, 4, 0, Math.PI * 2);
      ctx.fillStyle = pal.sage;
      ctx.fill();

      // Eyes blinking
      const blink = Math.abs(Math.sin(t * 1.8)) < 0.08 ? 1 : 4;
      ctx.fillStyle = pal.ink;
      ctx.fillRect(bx - 11, by - 8, 6, blink);
      ctx.fillRect(bx + 5, by - 8, 6, blink);

      // Voice Equalizer Waves on right
      const startX = w * 0.52;
      for (let i = 0; i < 8; i++) {
        const barH = 8 + Math.abs(Math.sin(t * 6 + i * 0.7)) * 34;
        ctx.fillStyle = i % 2 === 0 ? pal.terracotta : pal.sage;
        rRect(ctx, startX + i * 11, by - barH / 2, 6, barH, 3);
        ctx.fill();
      }
    },

    // 11. EDUCATION: Graduation Mortarboard Cap + CGPA 8.69 Academic Meter
    education: function (ctx, w, h, t, pal) {
      const cx = w * 0.28;
      const cy = h * 0.52 + Math.sin(t * 2.5) * 4;
      // Mortarboard diamond
      ctx.fillStyle = pal.ink;
      ctx.beginPath();
      ctx.moveTo(cx, cy - 22);
      ctx.lineTo(cx + 38, cy - 8);
      ctx.lineTo(cx, cy + 6);
      ctx.lineTo(cx - 38, cy - 8);
      ctx.closePath();
      ctx.fill();

      // Cap base
      ctx.fillRect(cx - 18, cy + 2, 36, 12);

      // Animated Tassel swinging
      const swing = Math.sin(t * 4) * 6;
      ctx.strokeStyle = pal.gold;
      ctx.lineWidth = 2.2;
      ctx.beginPath();
      ctx.moveTo(cx, cy - 8);
      ctx.lineTo(cx + 26 + swing, cy + 14);
      ctx.stroke();
      ctx.fillStyle = pal.terracotta;
      ctx.beginPath();
      ctx.arc(cx + 26 + swing, cy + 16, 4, 0, Math.PI * 2);
      ctx.fill();

      // CGPA 8.69 Progress Gauge on right
      const gx = w * 0.54;
      const gw = w * 0.38;
      const gy = h / 2 - 6;
      ctx.fillStyle = pal.surface;
      rRect(ctx, gx, gy, gw, 14, 7);
      ctx.fill();
      const fillW = gw * (0.869 * (0.85 + 0.15 * Math.sin(t * 2)));
      ctx.fillStyle = pal.sage;
      rRect(ctx, gx, gy, fillW, 14, 7);
      ctx.fill();
      ctx.fillStyle = pal.ink;
      ctx.font = 'bold 11px monospace';
      ctx.textAlign = 'left';
      ctx.fillText('VIT-AP M.Sc. DS • CGPA 8.69 / 10', gx, gy - 8);
    },

    // 12. CERTIFICATIONS: Official Credential Scroll + Pulsing Golden Seal
    certifications: function (ctx, w, h, t, pal) {
      const sx = w * 0.22;
      const sy = 20;
      const sw = w * 0.56;
      const sh = h - 40;
      ctx.fillStyle = pal.surface;
      ctx.strokeStyle = pal.border;
      ctx.lineWidth = 2;
      rRect(ctx, sx, sy, sw, sh, 8);
      ctx.fill();
      ctx.stroke();

      // Certificate lines
      ctx.strokeStyle = pal.muted;
      ctx.lineWidth = 2;
      for (let i = 0; i < 3; i++) {
        ctx.beginPath();
        ctx.moveTo(sx + 16, sy + 18 + i * 14);
        ctx.lineTo(sx + sw - 54, sy + 18 + i * 14);
        ctx.stroke();
      }

      // Pulsing Verified Seal & Ribbons
      const rx = sx + sw - 28;
      const ry = sy + sh / 2;
      const pulse = 12 + Math.sin(t * 4) * 2;
      ctx.fillStyle = pal.terracotta;
      ctx.beginPath();
      ctx.moveTo(rx - 6, ry + 8);
      ctx.lineTo(rx - 10, ry + 26);
      ctx.lineTo(rx - 2, ry + 22);
      ctx.moveTo(rx + 6, ry + 8);
      ctx.lineTo(rx + 10, ry + 26);
      ctx.lineTo(rx + 2, ry + 22);
      ctx.fill();

      ctx.beginPath();
      ctx.arc(rx, ry, pulse, 0, Math.PI * 2);
      ctx.fillStyle = pal.gold;
      ctx.fill();
      ctx.strokeStyle = pal.sage;
      ctx.lineWidth = 2;
      ctx.stroke();
    }
  };

  const sceneCanvases = document.querySelectorAll('canvas.scene-canvas');

  function resizeSceneCanvases() {
    sceneCanvases.forEach((c) => {
      const rect = c.getBoundingClientRect();
      if (rect.width > 0 && rect.height > 0) {
        c.width = rect.width;
        c.height = rect.height;
      }
    });
  }
  window.addEventListener('resize', resizeSceneCanvases);
  setTimeout(resizeSceneCanvases, 30);

  function animateScenes(now) {
    const t = now * 0.001;
    const pal = getPalette();

    sceneCanvases.forEach((c) => {
      if (c.width === 0 || c.height === 0) {
        const r = c.getBoundingClientRect();
        if (r.width > 0) {
          c.width = r.width;
          c.height = r.height;
        }
      }
      const key = c.getAttribute('data-scene');
      const fn = SCENE_RENDERERS[key];
      if (fn && c.width > 0 && c.height > 0) {
        const ctx = c.getContext('2d');
        ctx.clearRect(0, 0, c.width, c.height);
        fn(ctx, c.width, c.height, t, pal);
      }
    });

    requestAnimationFrame(animateScenes);
  }
  requestAnimationFrame(animateScenes);
})();